/* Core Editor Styles - Matching Figma Design */
.core-editor-textarea {
  width: 100%;
  min-height: 800px;
  background: transparent;
  border: none;
  outline: none;
  resize: none;
  font-family: 'Geist Mono', monospace;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.5;
  color: var(--app-text-primary);
  opacity: 0.8;
}

.core-editor-textarea::placeholder {
  color: var(--app-text-tertiary);
}

/* Helper Text Animation */
@keyframes pulse-subtle {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.animate-pulse-subtle {
  animation: pulse-subtle 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
